  "version": "1.0.39",
  "description": "Encrypt and decrypt sensitive temporary files with RSA and AES-GCM",
  "type": "module",
  "exports": {
    ".": "./dist/src/index.js",
    "./tui": "./dist/src/tui.js"
  },
