    "url": "git+https://github.com/Max10240/opencode-plugin-unicorn.git",
    "directory": "packages/opencode-plugin-sensitive-encrypt"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0",
    "@opencode/plugin": "^2.2.7"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
