import { Plugin } from "@opencode/plugin";
import { decryptEnvelope, encryptEnvelope, ENVELOPE_ALGORITHM, parsePublicKey } from "./crypto.js";
import { MAX_INLINE_CIPHERTEXT_BYTES, parseOptions } from "./options.js";
import { ensureDecryptKey, ensureEncryptPublicKey, existingDecryptPrivateKeyFiles, readCiphertextFile, readDecryptKey, readSecretFile, writeCiphertext, writePlaintext, } from "./paths.js";
import { EncryptPreview } from "./rpc.js";
export const TOOL_NAME = "encrypt_sensitive";
export const DECRYPT_TOOL_NAME = "decrypt_sensitive";
export const KEY_INFO_TOOL_NAME = "sensitive_key_info";
export const TOOL_DESCRIPTION = `Encrypt a single file under $TMPDIR with the configured public key only when the user explicitly requests it. Create it with \`mktemp\` and a shell redirect or pipe; never use the write/read tools, cat, or any other method that puts its contents in context. If \`out\` is used, keep it under $TMPDIR. Example: \`tmp=$(mktemp "\${TMPDIR:-/tmp}/secret.XXXXXX") && printf '%s' "$SECRET" > "$tmp" && echo "$tmp"\`, then call \`{"file":"<printed path>","out":"$TMPDIR/secret.ocsec"}\`.`;
export const DECRYPT_TOOL_DESCRIPTION = `Decrypt a single ocsec1 file under $TMPDIR into a new file with the configured private key only when the user explicitly requests it. Never output plaintext or key material; always write the result to out and report only its path. Keep out under $TMPDIR.`;
export const KEY_INFO_DESCRIPTION = "Show the configured public key and fingerprint without exposing private key material.";
function warn(role, error) {
    const message = error instanceof Error ? error.message : "unknown error";
    console.warn(`Sensitive ${role} disabled: ${message}`);
}
async function notifyProtection(context, tool, input) {
    try {
        const register = (await context.tool.list()).find((entry) => entry.id === "register_sensitive_file" || entry.name === "register_sensitive_file");
        if (!register)
            return false;
        await register.execute(input, tool);
        return true;
    }
    catch {
        // Protection is optional; registration failures must not affect encryption or decryption.
        return false;
    }
}
async function protectDecryptPrivateKeys(context, options, decryptKey, tool) {
    const files = await existingDecryptPrivateKeyFiles(options);
    if (files.length === 0)
        return true;
    let registered = true;
    for (const file of files) {
        const ok = await notifyProtection(context, tool, {
            file,
            role: "manual",
            label: "decrypt private key",
            ...(decryptKey !== undefined && file === decryptKey.path ? { keyID: decryptKey.keyID } : {}),
            sessionID: tool.sessionID,
            toolCallID: tool.id,
        });
        if (!ok)
            registered = false;
    }
    return registered;
}
function syntheticToolContext() {
    return {
        sessionID: "",
        agent: "",
        messageID: "",
        id: "",
        progress: async () => { },
        signal: new AbortController().signal,
    };
}
function decryptEnvelopeLimit(maxBytes) {
    return Math.min(maxBytes * 2 + 4096, 64 * 1024 * 1024 * 2 + 4096);
}
async function encryptFile(options, publicKey, input) {
    if (typeof input.file !== "string" || !input.file.trim())
        throw new Error("file is required");
    if (input.out !== undefined && (typeof input.out !== "string" || !input.out.trim())) {
        throw new Error("out must be a non-empty path");
    }
    const source = await readSecretFile(input.file, options.maxBytes);
    const envelope = encryptEnvelope(publicKey, source.data);
    const metadata = {
        algorithm: ENVELOPE_ALGORITHM,
        keyID: publicKey.kid,
        input: source.path,
        ciphertextBytes: Buffer.byteLength(envelope, "utf8"),
    };
    if (input.out === undefined) {
        if (metadata.ciphertextBytes > MAX_INLINE_CIPHERTEXT_BYTES) {
            throw new Error("Ciphertext is too large for inline output; specify out");
        }
        return {
            content: envelope,
            metadata,
            ciphertext: envelope,
            input: source.path,
        };
    }
    const out = await writeCiphertext(input.out, envelope, source.path);
    return {
        content: `Encrypted to ${out} (key ${publicKey.kid}).`,
        metadata: { ...metadata, out },
        ciphertext: metadata.ciphertextBytes <= MAX_INLINE_CIPHERTEXT_BYTES ? envelope : undefined,
        input: source.path,
        out,
    };
}
async function encryptText(options, publicKey, input) {
    if (typeof input.text !== "string" || input.text.length === 0)
        throw new Error("text is required");
    if (input.out !== undefined && (typeof input.out !== "string" || !input.out.trim())) {
        throw new Error("out must be a non-empty path");
    }
    const plaintext = Buffer.from(input.text, "utf8");
    if (plaintext.length > options.maxBytes)
        throw new Error(`text exceeds the ${options.maxBytes} byte limit`);
    const envelope = encryptEnvelope(publicKey, plaintext);
    const bytes = Buffer.byteLength(envelope, "utf8");
    const metadata = {
        algorithm: ENVELOPE_ALGORITHM,
        keyID: publicKey.kid,
        textBytes: plaintext.length,
        ciphertextBytes: bytes,
    };
    if (input.out === undefined) {
        if (bytes > MAX_INLINE_CIPHERTEXT_BYTES)
            throw new Error("Ciphertext is too large for inline output; specify out");
        return { ciphertext: envelope, metadata };
    }
    const out = await writeCiphertext(input.out, envelope, "");
    return { ciphertext: bytes <= MAX_INLINE_CIPHERTEXT_BYTES ? envelope : undefined, out, metadata };
}
function availableKeys(publicKey, decryptKey) {
    return [
        ...(decryptKey?.publicKey ? [{ role: "decrypt", keyID: decryptKey.keyID }] : []),
        ...(publicKey ? [{ role: "encrypt", keyID: publicKey.kid }] : []),
    ];
}
function defaultKeyRole(decryptKey) {
    return decryptKey?.publicKey ? "decrypt" : "encrypt";
}
function selectedKey(role, publicKey, decryptKey) {
    const selected = role === "decrypt" || role === "encrypt" ? role : defaultKeyRole(decryptKey);
    if (selected === "decrypt") {
        if (!decryptKey?.publicKey)
            throw new Error("Decryption public key is unavailable");
        return parsePublicKey(decryptKey.publicKey);
    }
    if (!publicKey)
        throw new Error("Encryption public key is unavailable");
    return publicKey;
}
function createEncryptTool(context, options, publicKey) {
    return {
        name: TOOL_NAME,
        options: { codemode: false },
        description: TOOL_DESCRIPTION,
        input: {
            type: "object",
            properties: {
                file: { type: "string", description: "Secret file under $TMPDIR; use $TMPDIR/path." },
                out: { type: "string", description: "Optional ciphertext path under $TMPDIR; overwrites a regular file atomically." },
            },
            required: ["file"],
            additionalProperties: false,
        },
        execute: async (rawInput, tool) => {
            const result = await encryptFile(options, publicKey, rawInput);
            const protectedFile = await notifyProtection(context, tool, {
                file: result.input,
                role: "encrypt-input",
                keyID: publicKey.kid,
                sessionID: tool.sessionID,
                toolCallID: tool.id,
            });
            const warning = protectedFile
                ? undefined
                : "Warning: the input file was not registered for local protection. It must be a single-line secret, a private key, or a structured file registered with format and keys.";
            return {
                // Inline encryption returns ciphertext as content; keep that contract and
                // surface the protection warning in metadata.
                content: result.out === undefined || warning === undefined ? result.content : `${result.content}\n${warning}`,
                metadata: { ...result.metadata, protected: protectedFile, ...(warning === undefined ? {} : { warning }) },
            };
        },
    };
}
function createDecryptTool(context, options, key, ensurePrivateKeyProtection) {
    return {
        name: DECRYPT_TOOL_NAME,
        options: { codemode: false },
        description: DECRYPT_TOOL_DESCRIPTION,
        input: {
            type: "object",
            properties: {
                file: { type: "string", description: "ocsec1 ciphertext file under $TMPDIR." },
                out: { type: "string", description: "Required plaintext output path under $TMPDIR; written with mode 0600." },
            },
            required: ["file", "out"],
            additionalProperties: false,
        },
        execute: async (rawInput, tool) => {
            const input = rawInput;
            if (typeof input.file !== "string" || !input.file.trim())
                throw new Error("file is required");
            if (typeof input.out !== "string" || !input.out.trim())
                throw new Error("out is required");
            const source = await readCiphertextFile(input.file, decryptEnvelopeLimit(options.maxBytes));
            const envelope = source.data.toString("utf8").trim();
            const current = await readDecryptKey(key.path);
            const plaintext = decryptEnvelope(envelope, current.privateKey);
            if (plaintext.length > options.maxBytes) {
                throw new Error(`decrypted file exceeds the ${options.maxBytes} byte limit`);
            }
            const out = await writePlaintext(input.out, plaintext, source.path);
            await ensurePrivateKeyProtection(tool);
            const metadata = {
                algorithm: ENVELOPE_ALGORITHM,
                keyID: current.keyID,
                input: source.path,
                out,
                plaintextBytes: plaintext.length,
            };
            const protectedFile = await notifyProtection(context, tool, {
                file: out,
                role: "decrypt-output",
                keyID: current.keyID,
                sessionID: tool.sessionID,
                toolCallID: tool.id,
            });
            return {
                content: protectedFile
                    ? `Decrypted to ${out} (key ${current.keyID}, bytes ${plaintext.length}).`
                    : `Decrypted to ${out} (key ${current.keyID}, bytes ${plaintext.length}).\nWarning: the output file was not registered for local protection. It must be a single-line secret, a private key, or a structured file registered with format and keys.`,
                metadata: { ...metadata, protected: protectedFile },
            };
        },
    };
}
function createKeyInfoTool(publicKey, decryptKey) {
    return {
        name: KEY_INFO_TOOL_NAME,
        options: { codemode: false },
        description: KEY_INFO_DESCRIPTION,
        input: {
            type: "object",
            properties: {
                role: { type: "string", enum: ["encrypt", "decrypt", "all"] },
            },
            required: [],
            additionalProperties: false,
        },
        execute: async (rawInput) => {
            const input = rawInput;
            const role = input.role === "encrypt" || input.role === "decrypt" ? input.role : "all";
            const keys = [];
            if ((role === "encrypt" || role === "all") && publicKey) {
                keys.push({
                    role: "encrypt",
                    keyID: publicKey.kid,
                    publicKey: publicKey.key.export({ type: "spki", format: "pem" }).toString(),
                });
            }
            if ((role === "decrypt" || role === "all") && decryptKey?.publicKey) {
                keys.push({
                    role: "decrypt",
                    keyID: decryptKey.keyID,
                    publicKey: decryptKey.publicKey,
                });
            }
            if (keys.length === 0)
                throw new Error(`No ${role} public key is available`);
            return {
                content: keys.map((item) => `${item.role} public key (${item.keyID}):\n${item.publicKey}`).join("\n\n"),
                metadata: { keys },
            };
        },
    };
}
export async function setupSensitiveEncrypt(context) {
    let options;
    try {
        options = parseOptions(context.options);
    }
    catch (error) {
        warn("encryption", error);
        return async () => { };
    }
    if (!options.enabled)
        return async () => { };
    let publicKey;
    if (options.encrypt) {
        try {
            publicKey = await ensureEncryptPublicKey(options);
        }
        catch (error) {
            warn("encryption", error);
        }
    }
    let decryptKey;
    if (options.decrypt) {
        try {
            decryptKey = await ensureDecryptKey(options);
        }
        catch (error) {
            warn("decryption", error);
        }
    }
    let privateKeyProtection;
    const ensurePrivateKeyProtection = (tool) => {
        if (privateKeyProtection)
            return privateKeyProtection;
        privateKeyProtection = protectDecryptPrivateKeys(context, options, decryptKey, tool).then((ok) => {
            if (!ok)
                privateKeyProtection = undefined;
            return ok;
        });
        return privateKeyProtection;
    };
    await ensurePrivateKeyProtection(syntheticToolContext());
    if (!publicKey && !decryptKey)
        return async () => { };
    const cleanups = [];
    try {
        const registration = await context.tool.transform((editor) => {
            if (publicKey)
                editor.add(createEncryptTool(context, options, publicKey));
            if (decryptKey)
                editor.add(createDecryptTool(context, options, decryptKey, ensurePrivateKeyProtection));
            editor.add(createKeyInfoTool(publicKey, decryptKey));
        });
        cleanups.push(() => registration.dispose());
        if (context.rpc && publicKey) {
            const rpc = await context.rpc.register(EncryptPreview, {
                keys: async (_rawInput, request) => {
                    const keys = availableKeys(publicKey, decryptKey);
                    if (keys.length === 0)
                        return request.error("unavailable", "No encryption key is available", {});
                    return { keys, defaultRole: defaultKeyRole(decryptKey) };
                },
                encryptText: async (rawInput, request) => {
                    const input = rawInput;
                    try {
                        const key = selectedKey(input.key, publicKey, decryptKey);
                        const result = await encryptText(options, key, input);
                        return {
                            ...(result.ciphertext === undefined ? {} : { ciphertext: result.ciphertext }),
                            ...(result.out === undefined ? {} : { out: result.out }),
                            keyID: key.kid,
                            bytes: result.metadata.ciphertextBytes,
                        };
                    }
                    catch {
                        return request.error("unavailable", "Unable to encrypt this text", {});
                    }
                },
                encrypt: async (rawInput, request) => {
                    const input = rawInput;
                    try {
                        const key = selectedKey(input.key, publicKey, decryptKey);
                        const result = await encryptFile(options, key, input);
                        await notifyProtection(context, syntheticToolContext(), {
                            file: result.input,
                            role: "encrypt-input",
                            keyID: key.kid,
                        });
                        return {
                            ...(result.ciphertext === undefined ? {} : { ciphertext: result.ciphertext }),
                            ...(result.out === undefined ? {} : { out: result.out }),
                            keyID: key.kid,
                            bytes: result.metadata.ciphertextBytes,
                        };
                    }
                    catch {
                        return request.error("unavailable", "Unable to encrypt this file", {});
                    }
                },
            });
            cleanups.push(() => rpc.dispose());
        }
    }
    catch (error) {
        await Promise.allSettled(cleanups.map((cleanup) => cleanup()));
        warn("encryption", error);
        return async () => { };
    }
    return async () => {
        await Promise.allSettled(cleanups.map((cleanup) => cleanup()));
    };
}
export default Plugin.define({
    id: "max10240.sensitive-encrypt",
    setup: setupSensitiveEncrypt,
});
